(7513611, 1199799, 101256, '<td valign="top">Very crisp, clean imagery - lots of interesting detail - very well done.</td>', 'Very crisp, clean imagery - lots of interesting detail - very well done.', '2017-05-14 16:56:34.000000', NULL, 1),
(7513614, 1199776, 101256, '<td valign="top">Little bit of fade between the rear mountain top and sky - better definition when viewed in the reflection - certainly meets the challenge criteria.</td>', 'Little bit of fade between the rear mountain top and sky - better definition when viewed in the reflection - certainly meets the challenge criteria.', '2017-05-14 16:57:56.000000', NULL, 1),
(7513618, 1199622, 101256, '<td valign="top">Nicely framed and captured, but loses some detail in the deep background - still a worthy entry.</td>', 'Nicely framed and captured, but loses some detail in the deep background - still a worthy entry.', '2017-05-14 16:59:12.000000', NULL, 1),
(7513620, 1199604, 101256, '<td valign="top">Very much like a Plein Air painting - best of the entries so far. Wonderful color control and depth of field - very well done.</td>', 'Very much like a Plein Air painting - best of the entries so far. Wonderful color control and depth of field - very well done.', '2017-05-14 17:01:07.000000', NULL, 1),
(7513623, 1199555, 101256, '<td valign="top">Perhaps a little more thought into composition here would have helped although the idea was a good one.</td>', 'Perhaps a little more thought into composition here would have helped although the idea was a good one.', '2017-05-14 17:02:05.000000', NULL, 1),
(7513625, 1199739, 101256, '<td valign="top">Excellent framing, perfect foreground control, a little more detail in the background would have helped, but it''s fine as it is.  Perfect 10.</td>', 'Excellent framing, perfect foreground control, a little more detail in the background would have helped, but it''s fine as it is.  Perfect 10.', '2017-05-14 17:03:00.000000', NULL, 1),
(7513630, 1199596, 101256, '<td valign="top">I get the impression of "not quite finished" with this image - minor little flaws like the brown edge at the upper left petal and not so subtle color blooms here and there - a little more work on this would have helped.</td>', 'I get the impression of "not quite finished" with this image - minor little flaws like the brown edge at the upper left petal and not so subtle color blooms here and there - a little more work on this would have helped.', '2017-05-14 17:05:17.000000', NULL, 1),
(7513631, 1199491, 67152, '<td valign="top">awesome capture of this bird of prey<br/>i fear that voters may not easily see deep DOF  in this shot without a background with something sharp in focus as well.</td>', 'awesome capture of this bird of preyi fear that voters may not easily see deep DOF  in this shot without a background with something sharp in focus as well.', '2017-05-14 17:05:38.000000', NULL, 1),
(7513632, 1199763, 101256, '<td valign="top">A very nice stock image of mountain scenery - well done.</td>', 'A very nice stock image of mountain scenery - well done.', '2017-05-14 17:06:03.000000', NULL, 1),
(7513636, 1199715, 101256, '<td valign="top">Very little background to enhance the over all impact of the image - rather bland subject matter, could have used a different angle with a more interesting background.</td>', 'Very little background to enhance the over all impact of the image - rather bland subject matter, could have used a different angle with a more interesting background.', '2017-05-14 17:07:27.000000', NULL, 1),
(7513668, 1199762, 101256, '<td valign="top">Good control, but the rather blank sky line ruins the whole image and the point about depth of field.</td>', 'Good control, but the rather blank sky line ruins the whole image and the point about depth of field.', '2017-05-14 17:29:09.000000', NULL, 1),
(7513669, 1199528, 101256, '<td valign="top">Not too much can be said about this - perfect in every aspect.  Well Done.</td>', 'Not too much can be said about this - perfect in every aspect.  Well Done.', '2017-05-14 17:29:45.000000', NULL, 1),
(7513670, 1199755, 101256, '<td valign="top">Very good control of color - crisp sharp background - interesting subject - very nicely done.</td>', 'Very good control of color - crisp sharp background - interesting subject - very nicely done.', '2017-05-14 17:30:34.000000', NULL, 1),
(7513671, 1199741, 101256, '<td valign="top">What can one say when one meets perfection - pure poetry in black and white - incredible and if I were King of The Universe, this would be the category winner.  Outstanding.</td>', 'What can one say when one meets perfection - pure poetry in black and white - incredible and if I were King of The Universe, this would be the category winner.  Outstanding.', '2017-05-14 17:31:52.000000', NULL, 1),
(7513674, 1199723, 101256, '<td valign="top">Wonderfully subtle colors, the red is a little over done however and kind of spoils the peaceful nature of the image. Still, a great entry into the challenge.</td>', 'Wonderfully subtle colors, the red is a little over done however and kind of spoils the peaceful nature of the image. Still, a great entry into the challenge.', '2017-05-14 17:33:22.000000', NULL, 1),
(7513678, 1199720, 101256, '<td valign="top">I feel this could be a little more exposed and/or contrasty - much too dark to present any significant details.</td>', 'I feel this could be a little more exposed and/or contrasty - much too dark to present any significant details.', '2017-05-14 17:34:18.000000', NULL, 1),
(7513684, 1199610, 101256, '<td valign="top">This is interesting in that we''re looking at a very nicely detailed background with detail loss in the foreground - a little more exposure or perhaps HDR treatment would make this a much better image.</td>', 'This is interesting in that we''re looking at a very nicely detailed background with detail loss in the foreground - a little more exposure or perhaps HDR treatment would make this a much better image.', '2017-05-14 17:35:30.000000', NULL, 1),
