(7513688, 1199786, 101256, '<td valign="top">A worthy snapshot quality image - fairly average.</td>', 'A worthy snapshot quality image - fairly average.', '2017-05-14 17:37:35.000000', NULL, 1),
(7513689, 1199717, 101256, '<td valign="top">I really wish there had been more detail in the trees which would have made this perfect....sadly, not. Still, a very interesting image with lots of green which is a difficult color to properly control.</td>', 'I really wish there had been more detail in the trees which would have made this perfect....sadly, not. Still, a very interesting image with lots of green which is a difficult color to properly control.', '2017-05-14 17:38:50.000000', NULL, 1),
