(7514307, 1199773, 12611, '<td valign="top">A fantastic brown! Would that it were so simple to take a great shot, one of the best in the entire challenge, imho, and confuse all the voters.</td>', 'A fantastic brown! Would that it were so simple to take a great shot, one of the best in the entire challenge, imho, and confuse all the voters.', '2017-05-17 11:57:18.000000', NULL, 0),
(7514309, 1199575, 12611, '<td valign="top">Fantastic urban commentary. Terrific depth.</td>', 'Fantastic urban commentary. Terrific depth.', '2017-05-17 11:59:02.000000', NULL, 0),
(7514310, 1199164, 12611, '<td valign="top">I really dig the feel here, what you left in, and what was not included in the room. The lighting seals the proverbial deal on the mood. Industrial but warm- mechanical but somehow human as well. Vastly underrated.</td>', 'I really dig the feel here, what you left in, and what was not included in the room. The lighting seals the proverbial deal on the mood. Industrial but warm- mechanical but somehow human as well. Vastly underrated.', '2017-05-17 12:00:23.000000', NULL, 0),
(7514313, 1199617, 12611, '<td valign="top">Love it Paul- forget the glass. This has the feel of post-impressionist depressing cafe scene. I can picture clearly the brushstrokes through the warm amber light and the maroon awning. Sometimes its not about the patent result, but the latent feeling created in the observer.</td>', 'Love it Paul- forget the glass. This has the feel of post-impressionist depressing cafe scene. I can picture clearly the brushstrokes through the warm amber light and the maroon awning. Sometimes its not about the patent result, but the latent feeling created in the observer.', '2017-05-17 12:04:01.000000', NULL, 0),
